-- Embedded SQL checks for previously untested Clover functions.

-- Preserve all existing/custom tests; the same definitions ship with their packs.

UPDATE rvbbit.operators SET tests='[{"name": "public_page_content", "sql": "SELECT rvbbit.clover_web_scrape(''https://example.com'')->>''markdown''", "expect": {"type": "contains", "value": "documentation examples"}, "description": "Fetch a real public page and verify extracted content, not just an HTTP success."}]'::jsonb WHERE name='clover_web_scrape' AND coalesce(tests,'[]'::jsonb)='[]'::jsonb;

UPDATE rvbbit.operators SET tests='[{"name": "markdown_projection", "sql": "SELECT rvbbit.clover_web_markdown(''https://example.com'')", "expect": {"type": "contains", "value": "documentation examples"}, "description": "The convenience wrapper must return the extracted Markdown."}]'::jsonb WHERE name='clover_web_markdown' AND coalesce(tests,'[]'::jsonb)='[]'::jsonb;

UPDATE rvbbit.operators SET tests='[{"name": "cited_answer", "sql": "WITH r AS MATERIALIZED (SELECT rvbbit.clover_web_research(''What purpose does IANA reserve example.com for? Cite the official source.'') AS v) SELECT (length(v->>''answer_markdown'')>20 AND jsonb_array_length(v->''sources'')>0 AND jsonb_array_length(v->''claims'')>0) FROM r", "expect": {"type": "exact", "value": "true"}, "description": "A real research call must return an answer, sources and claims."}]'::jsonb WHERE name='clover_web_research' AND coalesce(tests,'[]'::jsonb)='[]'::jsonb;

UPDATE rvbbit.operators SET tests='[{"name": "deep_cited_answer", "sql": "WITH r AS MATERIALIZED (SELECT rvbbit.clover_web_research_deep(''What purpose does IANA reserve example.com for? Cite the official source.'') AS v) SELECT (length(v->>''answer_markdown'')>20 AND jsonb_array_length(v->''sources'')>0 AND v->>''mode''=''deep'') FROM r", "expect": {"type": "exact", "value": "true"}, "description": "Deep research must preserve its requested mode and return a sourced answer."}]'::jsonb WHERE name='clover_web_research_deep' AND coalesce(tests,'[]'::jsonb)='[]'::jsonb;

UPDATE rvbbit.operators SET tests='[{"name": "watch_public_page", "sql": "WITH r AS MATERIALIZED (SELECT rvbbit.clover_web_watch(''What does this example domain page say?'', ''[\"https://example.com\"]'') AS v) SELECT (v->>''mode''=''watch'' AND jsonb_array_length(v->''sources'')>0 AND v ? ''changes'' AND v ? ''memory'') FROM r", "expect": {"type": "exact", "value": "true"}, "description": "Check a public page with the normal watch/snapshot contract. Runs on invocation; creates no scheduled watch."}]'::jsonb WHERE name='clover_web_watch' AND coalesce(tests,'[]'::jsonb)='[]'::jsonb;

UPDATE rvbbit.operators SET tests='[{"name": "named_decision", "sql": "SELECT rvbbit.clover_decide(''The customer says: please cancel my appointment.'', rvbbit.choice_question(ARRAY[''cancel'',''reschedule''])) #>> ''{answers,result,choice}''", "expect": {"type": "exact", "value": "cancel"}, "description": "Named question and selected route must survive the SQL decision wrapper."}]'::jsonb WHERE name='clover_decide' AND coalesce(tests,'[]'::jsonb)='[]'::jsonb;

UPDATE rvbbit.operators SET tests='[{"name": "explicit_model_choice", "sql": "SELECT rvbbit.clover_decide_model(to_jsonb(''Please cancel my appointment.''::text), rvbbit.choice_question(ARRAY[''cancel'',''reschedule'']), ''typesafe/jev-1.13'') #>> ''{answers,result,choice}''", "expect": {"type": "exact", "value": "cancel"}, "description": "Exercise the explicit model variant with Jev."}]'::jsonb WHERE name='clover_decide_model' AND coalesce(tests,'[]'::jsonb)='[]'::jsonb;

UPDATE rvbbit.operators SET tests='[{"name": "entity_spans", "sql": "SELECT rvbbit.clover_gliner_extract(''Alice works at Acme in Boston.'',''person,organization,location'')::text", "expect": {"type": "contains", "value": "Alice"}, "description": "Run the installed CPU model and recover a known person span."}]'::jsonb WHERE name='clover_gliner_extract' AND coalesce(tests,'[]'::jsonb)='[]'::jsonb;

UPDATE rvbbit.operators SET tests='[{"name": "portable_anomaly_model", "sql": "SELECT length(rvbbit.clover_analytics(''anomaly_fit'',''{\"X\":[[0,0],[1,1],[2,2],[3,3],[20,20]],\"algorithm\":\"isolation_forest\"}'')->>''blob_b64'') > 100", "expect": {"type": "exact", "value": "true"}, "description": "Fit a real CPU anomaly model and require its portable model payload."}]'::jsonb WHERE name='clover_analytics' AND coalesce(tests,'[]'::jsonb)='[]'::jsonb;

UPDATE rvbbit.operators SET tests='[{"name": "series_embedding", "sql": "WITH r AS MATERIALIZED (SELECT rvbbit.clover_tspulse(''timeseries_embed'',jsonb_build_object(''values'',(SELECT jsonb_agg(sin(i/10.0)) FROM generate_series(1,512) i))::text) AS v) SELECT ((v->>''dimension'')::int > 0 AND jsonb_array_length(v->''embedding'')=(v->>''dimension'')::int) FROM r", "expect": {"type": "exact", "value": "true"}, "description": "Run a 512-point series through TSPulse and verify the embedding dimension."}]'::jsonb WHERE name='clover_tspulse' AND coalesce(tests,'[]'::jsonb)='[]'::jsonb;

UPDATE rvbbit.operators SET tests='[{"name": "json_operator_spec", "sql": "SELECT rvbbit.clover_llm_draft_spec(''Return exactly one JSON operator specification named test_uppercase with arg_names [text], return_type text, prompt Uppercase {{text}}, and two tests for hello to HELLO and bye to BYE. Do not create it.'')::jsonb->>''name''", "expect": {"type": "exact", "value": "test_uppercase"}, "description": "Generate and parse a draft specification without installing or executing it."}]'::jsonb WHERE name='clover_llm_draft_spec' AND coalesce(tests,'[]'::jsonb)='[]'::jsonb;
